import { createReadStream } from "node:fs";
import fs from "node:fs/promises";
import path from "node:path";
import type { Readable } from "node:stream";
import type { StorageService } from "./StorageService";

// Keys are generated by us (uuid + extension). Anything else is rejected,
// which also prevents path traversal like "../../etc/passwd".
const SAFE_KEY = /^[a-f0-9-]{36}\.(pdf|jpg|png)$/;

export class LocalStorage implements StorageService {
  private readonly root: string;

  constructor(rootDir: string) {
    this.root = path.resolve(rootDir);
  }

  async init(): Promise<void> {
    await fs.mkdir(this.root, { recursive: true });
  }

  private resolve(key: string): string {
    if (!SAFE_KEY.test(key)) throw new Error(`Invalid storage key: ${key}`);
    return path.join(this.root, key);
  }

  async save(key: string, data: Buffer): Promise<void> {
    await fs.writeFile(this.resolve(key), data);
  }

  async read(key: string): Promise<Buffer> {
    return fs.readFile(this.resolve(key));
  }

  async createReadStream(key: string): Promise<Readable> {
    const filePath = this.resolve(key);
    await fs.access(filePath);
    return createReadStream(filePath);
  }

  async delete(key: string): Promise<void> {
    await fs.rm(this.resolve(key), { force: true });
  }
}
